_NAV = (
    ('/', 'Главная'),
    ('/review', 'Проверка'),
    ('/offers', 'Предложения'),
    ('/sources-registry', 'Источники'),
    ('/network', 'Сеть'),
    ('/runs', 'Журнал'),
    ('/system', 'Система'),
    ('/onboarding/1', 'Интеграции'),
)


def brand_header(path: str) -> str:
    links = []
    for href, label in _NAV:
        active = path == href or (href != '/' and path.startswith(href + '/'))
        links.append(f'<a href="{href}" class="{"active" if active else ""}">{html.escape(label)}</a>')
    return f'''<header class="arv-header"><div class="arv-header-inner"><div class="arv-brand-row"><div>{ARVECTUM_LOGO_SVG}<div class="arv-product">Discount Parser · control panel</div></div></div><nav class="arv-nav">{"".join(links)}</nav></div></header>'''


def brand_footer() -> str:
    return '''<footer class="arv-footer"><div class="arv-footer-inner"><div class="arv-footer-top"></div><div class="arv-footer-grid"><div><strong>ООО «Арвектум»</strong><div>IT-компания: цифровые продукты, автоматизация и AI-решения</div><div style="margin-top:8px"><a href="https://arvectum.com" target="_blank" rel="noopener">arvectum.com</a> · <a href="mailto:info@arvectum.com">info@arvectum.com</a></div></div><div class="mono">ИНН 7716261422 · КПП 771601001<br>ОГРН 1267700213725<br>129337, г. Москва, Ярославское ш., д. 107, к. 2, кв. 75</div></div><div class="arv-copyright">© 2026 ООО «Арвектум». Все права защищены.</div></div></footer>'''
